let input = null;
try { input = $('Input').item.json; } catch (e) { input = null; }
return [{ json: {
  requested_by: (input && input.requested_by) || 'manual',
  category: (input && input.category) || '',
  slug: (input && input.slug) || '',
  channel_id: (input && input.channel_id) || 'C0BQH5S6P1P'
} }];

const input = $('Config').item.json;
const category = String(input.category || '').trim();
const slug = String(input.slug || '').trim();
return $input.all()
  .map(i => i.json)
  .filter(c => (!category || c.category === category) && (!slug || c.slug === slug))
  .map(c => ({ json: c }));

const runId = $('Run Id').first().json.run_id;
const caseRows = $('Filter Cases').all();
const expected = caseRows.length;
const meta = {};
for (const c of caseRows) meta[c.json.id] = { slug: c.json.slug, ctx: Array.isArray(c.json.context_messages) ? c.json.context_messages.length : 0 };
const rows = $input.all().map(i => i.json).filter(r => r.run_id === runId);
const seen = new Set();
const unique = [];
for (const r of rows) {
  if (!r.case_id || seen.has(r.case_id)) continue;
  seen.add(r.case_id);
  unique.push(r);
}
const counts = { pass: 0, fail: 0, error: 0, pending: 0 };
const cases = unique.map(r => {
  counts[r.status] = (counts[r.status] || 0) + 1;
  const m = meta[r.case_id] || {};
  let metrics = r.metrics;
  if (typeof metrics === 'string') { try { metrics = JSON.parse(metrics); } catch (e) { metrics = null; } }
  return {
    slug: m.slug || r.case_slug || r.case_id,
    ctx: m.ctx || 0,
    status: r.status,
    called_tools: r.called_tools,
    execution_url: r.execution_url || null,
    metrics: metrics
  };
});
cases.sort((a, b) => (a.slug < b.slug ? -1 : 1));
const poll = ($runIndex || 0) + 1;
return [{ json: {
  run_id: runId,
  expected: expected,
  landed: unique.length,
  polls: poll,
  complete: unique.length >= expected,
  timeout: poll >= 90,
  pass: counts.pass,
  fail: counts.fail,
  error: counts.error,
  cases: cases
} }];

const r = $input.first().json;
const baseUrl = String($vars.instance_url || 'https://darwin-staging.app.n8n.cloud').replace(/\/$/, '');
const execUrl = baseUrl + '/workflow/' + $workflow.id + '/executions/' + $execution.id;

const ICON = { pass: '✅', fail: '❌', error: '💥', pending: '⏳' };
const cell = t => String(t).replace(/\|/g, '\\|').replace(/\n+/g, ' ');
const fmt = v => (v === null || v === undefined) ? '-' : Number(v).toFixed(2);

const total = r.cases.length;
const passed = r.cases.filter(c => c.status === 'pass').length;
const pct = total ? ((passed / total) * 100).toFixed(1) : 'n/a';

const lines = [];
lines.push('## Retrieval evals (Slack transport) — `' + r.run_id + '`', '');
lines.push('**' + (r.complete ? 'Complete' : 'Incomplete (timeout)') + '** · ' + r.landed + '/' + r.expected + ' landed · ' + r.polls + ' polls · **' + passed + '/' + total + ' pass (' + pct + '%)**', '');
lines.push('| Case | Tools called | Execution | Score | Reason |');
lines.push('| --- | --- | --- | --- | --- |');
for (const c of r.cases) {
  const m = c.metrics || {};
  const ret = m.retrieval || {};
  const name = '`' + c.slug + '`' + (c.ctx ? ' _(+' + c.ctx + ' ctx)_' : '');
  const tools = (Array.isArray(c.called_tools) ? c.called_tools : []).map(t => '`' + t + '`').join(' ') || '—';
  const exec = c.execution_url ? '<' + c.execution_url + '|exec>' : '—';
  const score = (ICON[c.status] || c.status) + ' mrr ' + fmt(ret.mrr) + ' · ' + (m.retrieval_hits != null ? m.retrieval_hits : 0) + ' hits';
  const reason = m.reason || (c.status === 'pass' ? '—' : 'see metrics');
  lines.push('| ' + [cell(name), cell(tools), exec, cell(score), cell(reason)].join(' | ') + ' |');
}

lines.push('', '_Generated ' + new Date().toISOString() + '_ · <' + execUrl + '|Dispatcher execution>');
return [{ json: { markdown: lines.join('\n'), run_id: r.run_id, pass: passed, total: total } }];

// Build Slack Block Kit markdown blocks from the Summary node's markdown output.
// Splits long text across multiple mrkdwn blocks (3,000-char limit each),
// up to ~90KB total serialized JSON payload to stay within Slack API limits.
// Splits on newlines where possible. Ported from the "Slack" workflow (9UJFDlOnoxSzFCS1).

const PER_BLOCK = 2900;  // leave margin under Slack's 3000-char limit
const MAX_BLOCKS = 50;   // hard cap: Slack max 50 blocks
const MAX_PAYLOAD_BYTES = 90000;  // ~90KB budget for serialized { blocks: [...] }
const TRUNCATION_NOTE = '\n\n_… (truncated: response too long for a single Slack message)_';

let text = $json.markdown ?? '';
const fullText = text;  // preserve original for downstream use

// --- Helper: estimate serialized size of a blocks array ---
function estimatePayloadSize(blocksArr) {
  // Serialize just the blocks array; the outer { "blocks": [...] } wrapper adds ~15 chars
  return JSON.stringify(blocksArr).length + 20;
}

// --- Split text into chunks ---
function splitIntoChunks(str, chunkSize, maxBlocks, maxBytes) {
  const chunks = [];
  const trialBlocks = [];

  while (str.length > 0 && chunks.length < maxBlocks) {
    if (str.length <= chunkSize) {
      chunks.push(str);
      trialBlocks.push({ type: 'markdown', text: str });
      if (estimatePayloadSize(trialBlocks) > maxBytes) {
        const removed = chunks.pop();
        trialBlocks.pop();
        const remaining = maxBytes - estimatePayloadSize(trialBlocks);
        const maxTextLen = Math.max(0, remaining - 60);
        if (maxTextLen > 50) {
          chunks.push(removed.slice(0, maxTextLen) + TRUNCATION_NOTE);
        }
      }
      break;
    }

    // Try to find last newline within the chunk boundary
    const sliceTarget = str.slice(0, chunkSize);
    const lastNewline = sliceTarget.lastIndexOf('\n');
    let chunk;
    if (lastNewline > chunkSize - 500) {
      chunk = str.slice(0, lastNewline);
      str = str.slice(lastNewline + 1);
    } else {
      chunk = sliceTarget;
      str = str.slice(chunkSize);
    }

    const tentativeBlocks = [...trialBlocks, { type: 'markdown', text: chunk }];
    if (estimatePayloadSize(tentativeBlocks) > maxBytes) {
      const remaining = maxBytes - estimatePayloadSize(trialBlocks);
      const maxTextLen = Math.max(0, remaining - 60);
      if (maxTextLen > 50) {
        chunks.push(chunk.slice(0, maxTextLen) + TRUNCATION_NOTE);
      }
      break;
    }

    chunks.push(chunk);
    trialBlocks.push({ type: 'markdown', text: chunk });
  }

  if (str.length > 0 && chunks.length === maxBlocks) {
    chunks[chunks.length - 1] = chunks[chunks.length - 1].replace(/\n*$/, '') + TRUNCATION_NOTE;
  }

  return chunks;
}

const chunks = splitIntoChunks(text, PER_BLOCK, MAX_BLOCKS, MAX_PAYLOAD_BYTES);
const blocks = chunks.map(t => ({ type: 'markdown', text: t }));
const content = { blocks };

return [{ json: { blocksJson: JSON.stringify(content), output: fullText } }];

// Group the formatted blocks into message-sized chunks so no single Slack
// message exceeds Slack's cumulative block-text limit (~13k chars, undocumented —
// see slackapi/bolt-js#2509). Emits one item per message; Send a message then posts
// one message per item. Ported from the "Slack" workflow (9UJFDlOnoxSzFCS1).
const MSG_BUDGET = 8000; // chars of block text per message, safe margin under ~13k

const blocksJson = $('format').first().json.blocksJson;

let blocks;
try {
  blocks = JSON.parse(blocksJson).blocks;
  if (!Array.isArray(blocks) || blocks.length === 0) throw new Error('no blocks');
} catch (e) {
  // Fall back to previous single-message behaviour if parsing fails
  return [{ json: { blocksJson, part: 1, totalParts: 1 } }];
}

const messages = [];
let current = [];
let currentLen = 0;

for (const block of blocks) {
  const len = (block.text || '').length;
  if (current.length > 0 && currentLen + len > MSG_BUDGET) {
    messages.push(current);
    current = [];
    currentLen = 0;
  }
  current.push(block);
  currentLen += len;
}
if (current.length > 0) messages.push(current);

return messages.map((msgBlocks, i) => ({
  json: {
    blocksJson: JSON.stringify({ blocks: msgBlocks }),
    part: i + 1,
    totalParts: messages.length,
  },
}));
